def wrap_(text, width):
    if width <= 0:
        raise ValueError("invalid width")

    # Expand tabs to spaces (tabsize=8 by default)
    expanded = ""
    col = 0
    for ch in text:
        if ch == '\t':
            spaces = 8 - (col % 8)
            expanded += ' ' * spaces
            col += spaces
        else:
            expanded += ch
            col += 1

    # Replace each whitespace character with a single space (runs are NOT collapsed)
    result_chars = []
    col = 0
    for ch in text:
        if ch == '\t':
            spaces = 8 - (col % 8)
            for _ in range(spaces):
                result_chars.append(' ')
                col += 1
        elif ch.isspace():
            result_chars.append(' ')
            col += 1
        else:
            result_chars.append(ch)
            col += 1

    processed = ''.join(result_chars)

    # Split into tokens: alternating between words and individual spaces
    tokens = []
    i = 0
    n = len(processed)
    while i < n:
        if processed[i].isspace():
            tokens.append(' ')
            i += 1
        else:
            j = i
            while j < n and not processed[j].isspace():
                j += 1
            tokens.append(processed[i:j])
            i = j

    lines = []
    current_line = []
    current_len = 0
    at_start = True

    for token in tokens:
        if token == ' ':
            if current_len == 0 and not at_start:
                continue
            if current_len + 1 > width:
                while current_line and current_line[-1] == ' ':
                    current_line.pop()
                    current_len -= 1
                if current_line:
                    lines.append(''.join(current_line))
                current_line = []
                current_len = 0
                continue
            current_line.append(' ')
            current_len += 1
        else:
            word = token
            if current_len + len(word) <= width:
                current_line.extend(word)
                current_len += len(word)
            else:
                remaining = width - current_len
                if remaining > 0:
                    current_line.extend(word[:remaining])
                    current_len += remaining
                    word = word[remaining:]

                while current_line and current_line[-1] == ' ':
                    current_line.pop()
                    current_len -= 1
                if current_line:
                    lines.append(''.join(current_line))
                current_line = []
                current_len = 0

                while len(word) > width:
                    current_line.extend(word[:width])
                    lines.append(''.join(current_line))
                    current_line = []
                    current_len = 0
                    word = word[width:]

                if word:
                    current_line.extend(word)
                    current_len += len(word)

        at_start = False

    if current_line:
        while current_line and current_line[-1] == ' ':
            current_line.pop()
        if current_line:
            lines.append(''.join(current_line))

    return lines
